import{_,o as a,c as r,a2 as e}from"./chunks/framework.F7eQ-ohH.js";const b=JSON.parse('{"title":"什么是语境分析？","description":"","frontmatter":{},"headers":[],"relativePath":"行测/言语理解/8、语境分析.md","filePath":"行测/言语理解/8、语境分析.md","lastUpdated":1788883925000}'),d={name:"行测/言语理解/8、语境分析.md"};function o(n,t,p,h,s,l){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="什么是语境分析" tabindex="-1">什么是语境分析？ <a class="header-anchor" href="#什么是语境分析" aria-label="Permalink to &quot;什么是语境分析？&quot;">​</a></h1><p>语境分析是逻辑填空的核心解题方法，通过梳理文段上下文的逻辑关系，帮助考生精准把握语境背景、锁定空缺处语义，进而做出契合文意的选择。逻辑填空中常见的上下文关系共 9 类，具体包括：并列关系、递进关系、选择关系、转折关系、假设关系、条件关系、因果关系、承接关系、解释说明关系，另有对照关系（反义）作为补充考点。</p><p><strong>例题</strong>：在京剧艺术舞台上，一个圆场，也许就表示走出百里之外；几声更鼓，在短暂的时间内则已是夜尽天明。这种时空的二重性，使得舞台的局限性巧妙地转化为艺术的________。为了反映多种多样的生活场景，则往往打破舞台条件的制约，而采取________的手法来表现规定场景，如花园、战场、江河等。填入划横线部分最恰当的一项是：</p><p>A. 灵活性 虚构 B. 丰富性 抽象 C. 广阔性 艺术 D. 多样性 夸张</p><p><strong>答案</strong>：C</p><p><strong>解析</strong>：第一空，前文 “局限性” 与空缺处形成语义对立，“广阔性” 直接呼应 “百里之外”“夜尽天明” 的时空拓展属性；第二空，“打破舞台制约” 需通过京剧特有的表现形式实现，“艺术手法” 为固定搭配，契合语境逻辑。</p><p>上面是一个语境分析的例子，简单来说，语境分析类题的解题重点在于，不孤立看待单个空缺词，而是通过上下文的关联信息（比如标志词、语义呼应、句式特征等），推导空缺处应填词语的含义、感情色彩、搭配习惯，从而排除不符合语境的干扰项。</p><h1 id="上下文关系分类" tabindex="-1">上下文关系分类 <a class="header-anchor" href="#上下文关系分类" aria-label="Permalink to &quot;上下文关系分类&quot;">​</a></h1><h2 id="并列关系" tabindex="-1">并列关系 <a class="header-anchor" href="#并列关系" aria-label="Permalink to &quot;并列关系&quot;">​</a></h2><p>【<strong>定义：</strong> 并列关系指多个事物或动作同时存在，无主次之分，语义相近或互补。 <strong>标志词：</strong> 和、与、并、又、既… 又…、也、分号（;）、顿号（、）、句式一致（排比 / 类比）等。小明喜欢苹果🍎、香蕉🍌和橘子🍊。 <strong>示例：</strong> 小明喜欢苹果🍎、香蕉🍌和橘子；欧美国家示威、罢工活动此起彼伏，暴力事件频发，社会乱象层出不穷。 】</p><p><strong>例题</strong>：书法艺术在总体上是一种________美，它与人品的关系曲折错综。许多性格柔弱的文人却有一副________的笔墨，而沙场猛将的字迹倒未必有________之气。</p><p>A. 形象 奇崛 暴戾</p><p>B. 形象 雄健 杀伐</p><p>C. 形式 雄健 暴戾</p><p>D. 形式 奇崛 杀伐</p><p><strong>答案</strong>：D</p><p><strong>解析</strong>： 第一空与“美”搭配，“形式美”更符合艺术范畴（“形象”多指具体事物）；第二空通过“却”形成对比，与“性格柔弱”对立，选“奇崛”（新奇刚健）；第三空与“沙场猛将”对应，“杀伐之气”符合语境且无贬义，排除“暴戾”。</p><h2 id="递进关系" tabindex="-1">递进关系 <a class="header-anchor" href="#递进关系" aria-label="Permalink to &quot;递进关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>定义：后文语义比前文更重、范围更广，重点在递进后内容。标志词：不仅… 还…、甚至、更、而且、愈加、进而等。示例：小红不仅考了满分💯，还拿到了奖学金💰；他不但学习好，而且品德优秀（强调 “品德优秀”）。</th></tr></thead></table><p><strong>例题</strong>：心理学家根据临床观察发现，我们生活中的许多 “抑郁症” 属于假性抑郁症，一般人的情绪变化有一定______，通常是短期的，人们通过自我调适即可恢复。</p><p>A. 突发性 B. 周期性 C. 时限性 D. 反复性</p><p><strong>答案</strong>：C</p><p><strong>解析</strong>：后文 “通常是短期的” 是对前文的递进解释，“时限性” 直接强调时间限制，与 “短期” 形成语义呼应，其余选项均无 “时间限定” 的核心语义。</p><h2 id="选择关系" tabindex="-1">选择关系 <a class="header-anchor" href="#选择关系" aria-label="Permalink to &quot;选择关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>定义：在两个或多个选项中择一，语义互斥。标志词：要么… 要么…、或者… 或者… 等。示例：你要么现在写作业📖，要么明天早起补；今天晚上或者看书，或者看电视（二者选一）。</th></tr></thead></table><p><strong>例题</strong>：“你要么现在写作业，要么明天早起补！” 这句话中的逻辑关系是：</p><p>A. 假设关系</p><p>B. 选择关系</p><p>C. 条件关系</p><p>D. 因果关系</p><p><strong>答案</strong>：B</p><p><strong>解析</strong>：“要么… 要么…” 是选择关系的典型标志词，明确表示二选一的语义，与其他逻辑关系特征不符。</p><h2 id="转折关系" tabindex="-1">转折关系 <a class="header-anchor" href="#转折关系" aria-label="Permalink to &quot;转折关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>定义：前后语义相反或相对，重点在转折后内容。标志词：但是、可是、却、然而、事实上、实际上、反而等。示例：虽然下雨了🌧️，但小明还是坚持去踢足球⚽；虽然今天下雨了，但是同学们依然按时到校（强调 “按时到校”）。</th></tr></thead></table><p><strong>例题</strong>：虽然形式相同，意义却______。如果不能正确解读可能引起严重后果。</p><p>A. 南辕北辙</p><p>B. 针锋相对</p><p>C. 截然相反</p><p>D. 纷繁复杂</p><p><strong>答案</strong>：C</p><p><strong>解析</strong>：“虽然… 却…” 引导转折关系，后文强调 “语义不同且后果严重”，“截然相反” 直接体现完全对立的语义，程度契合语境；“南辕北辙” 侧重行动与目标相反，“针锋相对” 侧重观点对立，“纷繁复杂” 侧重杂乱，均不贴合 “意义对立” 的核心需求。</p><h2 id="假设关系" tabindex="-1">假设关系 <a class="header-anchor" href="#假设关系" aria-label="Permalink to &quot;假设关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>定义：假设某种前提条件，进而说明对应结果，常隐含对策或倾向。标志词：如果… 就…、假如… 那么…、若… 则…、即使… 也… 等。示例：如果明天不下雨🌤️，我们就去野餐；若与中医结合，定能弥补癌症治疗不足（强调 “中西医结合”）。</th></tr></thead></table><p><strong>例题</strong>：“如果与中医结合，定能弥补癌症治疗不足。” 这句话强调：</p><p>A. 中医的局限性</p><p>B. 中西医结合的必要性</p><p>C. 癌症治疗的难度</p><p>D. 假设的不可行性</p><p><strong>答案</strong>：B</p><p><strong>解析</strong>：“如果… 定能…” 构成假设关系，结果部分 “弥补不足” 隐含核心对策 —— 中西医结合，直接体现其必要性，其余选项均偏离语义重点。</p><h2 id="条件关系" tabindex="-1">条件关系 <a class="header-anchor" href="#条件关系" aria-label="Permalink to &quot;条件关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>定义：需满足特定条件方可产生对应结果，核心强调条件的重要性。标志词：只有… 才…、只要… 就…、除非… 否则…、必须、需要等。示例：只有写完作业📝，才能看电视📺；只有认真学习，才能考上公务员（强调 “认真学习”）。</th></tr></thead></table><p><strong>例题</strong>：“只有尽快提高农民素质，才能推广农业技术。” 这句话的核心是：</p><p>A. 农民现状 B. 技术推广难点 C. 提高素质的条件性 D. 农业技术的重要性</p><p><strong>答案</strong>：C</p><p><strong>解析</strong>：“只有… 才…” 明确条件关系，“提高农民素质” 是 “推广农业技术” 的必要条件，核心强调 “提高素质” 的前提作用，即条件性，其余选项均未体现 “条件 - 结果” 的逻辑核心。</p><h2 id="因果关系" tabindex="-1">因果关系 <a class="header-anchor" href="#因果关系" aria-label="Permalink to &quot;因果关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>定义：前因后果的逻辑关联，重点在结果（若结果为对策 / 结论，需优先关注）。标志词：因为… 所以…、因此、由于、导致、使得、于是等。示例：因为昨晚没睡好😴，所以今天上课打瞌睡💤；天太热了🔥，导致冰淇淋全化了🍦（因：热，果：融化）。</th></tr></thead></table><p><strong>例题</strong>：“因为昨晚没睡好，所以今天上课打瞌睡。” 若删去 “因为”，需保留：</p><p>A. 因此 B. 但是 C. 甚至 D. 于是</p><p><strong>答案</strong>：A</p><p><strong>解析</strong>：因果关系需保留结果导向的标志词，“因此” 可直接替代 “因为… 所以…” 的逻辑结构，承接前因、引出结果；“于是” 侧重承接动作，语义不及 “因此” 贴合因果关联，其余选项无因果逻辑属性。</p><h2 id="承接关系" tabindex="-1">承接关系 <a class="header-anchor" href="#承接关系" aria-label="Permalink to &quot;承接关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>定义：动作或事件按时间顺序、逻辑顺序连续发生，无语义对立或递进。标志词：接着、然后、于是、之后、先… 再… 等。示例：小华先洗手🖐️，然后开始吃饭🍚；他打开书包，拿出铅笔，开始写作业（按时间顺序推进）。</th></tr></thead></table><p><strong>例题</strong>：“他打开书包，拿出铅笔，开始写作业。” 这三步的承接关系是：</p><p>A. 时间顺序 B. 逻辑递进 C. 空间转移 D. 对比并列</p><p><strong>答案</strong>：A</p><p><strong>解析</strong>：“打开书包→拿出铅笔→开始写作业” 是按动作发生的时间先后顺序描述，符合承接关系的核心特征，无逻辑递进、空间转移或对比并列的语义。</p><h2 id="上下文关系汇总" tabindex="-1">上下文关系汇总 <a class="header-anchor" href="#上下文关系汇总" aria-label="Permalink to &quot;上下文关系汇总&quot;">​</a></h2><table tabindex="0"><thead><tr><th>逻辑关系</th><th>标志词/符号</th><th>解题技巧</th><th>示例</th></tr></thead><tbody><tr><td>并列关系</td><td>也、和、与、并、又、还、分号（;）、顿号（;）、句式一致（排比、类比）等</td><td>1. 语义相近或互补，需全面概括；2. 结构上保持词性一致或顺序一致。</td><td>例：欧美国家示威、罢工活动____，暴力事件频发，社会乱象____（答案：此起彼伏、层出不穷）</td></tr><tr><td>递进关系</td><td>甚至、更、进而、不仅…而且…、还、愈加等</td><td>1. 语义程度前轻后重；2. 重点在递进后的内容。</td><td>例：他不但学习好，而且品德优秀（强调“品德优秀”更关键）</td></tr><tr><td>转折关系</td><td>但是、然而、却、事实上、实际上、反而、不是…而是…等</td><td>1. 前后语义或感情色彩相反；2. 重点在转折后，可能引出对策或新观点。</td><td>例：虽然今天下雨了，但是同学们依然按时到校（强调“按时到校”）</td></tr><tr><td>因果关系</td><td>因为…所以…、因此、由于、导致、使得等</td><td>1. 结果部分常为重点；2. 若结果是对策或结论，需优先关注。</td><td>例：只有尽快提高农民素质，才能推广农业技术（强调“提高农民素质”）</td></tr><tr><td>假设关系</td><td>如果…就…、即使…也…、若…则…等</td><td>1. 正向假设强调条件；2. 反向假设强调危害，间接引出对策。</td><td>例：若与中医结合，定能弥补癌症治疗不足（强调“中西医结合”）</td></tr><tr><td>条件关系</td><td>只有…才…、必须、除非…否则…、需要等</td><td>1. 必要条件是对策，需重点把握；2. 条件句中“只有”后的内容为核心。</td><td>例：只有认真学习，才能考上公务员（强调“认真学习”）</td></tr><tr><td>选择关系</td><td>要么…要么…、或者…或者…等</td><td>1. 表示在几种情况中选择其一；2. 注意语义上的互斥性。</td><td>例：今天晚上或者看书，或者看电视（二者选一）</td></tr><tr><td>解释说明关系</td><td>即、也就是说、例如、譬如、冒号（:）、破折号（——）等</td><td>1. 前后内容互为补充或限定；2. 需结合上下文明确空缺处语义。</td><td>例：数学公式可以简洁表达原理，这的确妙不可言（“这”指代前文内容）</td></tr><tr><td>对照关系（反义）</td><td>不是…而是…、是…不是…、多一些…少一些…等</td><td>1. 强调对立面，重点在肯定部分；2. 需注意与转折关系的区别（无主次之分）。</td><td>例：不是想逃学，而是病了（强调“病了”）</td></tr></tbody></table><h1 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h1><p>| 【中储粮2019】刚从事遥感考古工作的同志，________希望能验证一下自己的成果，_____希望在验证过程中获取经验和教训， ________有误，________可以弄清失误的原因，找到正确的方向。 A. 即使 也 不但 更； B. 也 更 即使 不但； C. 不但 更 即使 也； D. 更 也 不但 即使 答案 ：C</p><table tabindex="0"><thead><tr><th>解析 ：第一二空“验证成果”到“获取经验教训”是 递进关系 （“不但…更…”）；第三四空“有误”到“弄清原因”是 假设关系 （“即使…也…”）</th></tr></thead></table><p>| 【中国联通2024】生物分子计算机是一种用生物分子元件组装成的纳米级计算机，将其植入人体能自动扫描身体信号、_________生理指标、_________疾病并控制药物释放等。但研究人员指出，要实现这一________还要克服很多障碍。 A. 监测 判断 目标； B. 记录 查找 理想； C. 显示 治疗 技术； D. 检测 诊断 愿景 答案 ：D</p><table tabindex="0"><thead><tr><th>解析 ：第二空“诊断疾病”与后文“控制药物释放”形成 解释说明关系 （根据疾病状况控制药物）；第三空“愿景”对应“要实现”的目标</th></tr></thead></table><p>| 【国家能源2018】留得青山在，不怕没柴烧，已经成为一些人不思进取的借口。不要再有“留得青山在，不怕没柴烧”的侥幸，留得青山在，也怕没柴烧。青山不是资本，可能只是一线希望。吝惜“青山”会颓废你的心灵，吝惜“青山”会埋没你的斗志。这段话是要告诉我们？ A. 人生苦短，如白驹过隙； B. 把握今天胜于等待明天； C. 留得青山在，也许没柴烧； D. 要苦心志，砺筋骨 答案 ：D</p><table tabindex="0"><thead><tr><th>解析 ：“不要再有…侥幸”“吝惜‘青山’会颓废心灵、埋没斗志”通过 转折关系 强调，要放弃侥幸、磨炼意志</th></tr></thead></table><p>| 【中航工业2025】怀疑，常常是获得真知的先导，是打开知识宝库的钥匙。科学家李四光有句名言：“不怀疑不能见真理。”这句话颇为深刻。一般说来，________________。而问题的解决，便是获得真知灼见的开始。数学家华罗庚之所以能在数学领域里取得一个又一个的优异成果，正是由于他对书本上现成的公式、定理和结论，能够大胆怀疑，科学质疑。他攀登科学高峰的第一步也就是从这里开始的。 A. 大胆怀疑与科学质疑往往是连在一起的，问题是在深入研究中提出的，又必然会在怀疑中解决； B. 问题是在怀疑中提出的，又必然会在深入研究中解决，大胆怀疑与科学释疑往往是连在一起的； C. 问题是在深入研究中提出的，又必然会在怀疑中解决，大胆怀疑与科学释疑往往是连在一起的； D. 大胆怀疑与科学释疑往往是连在一起的，问题是在怀疑中提出的，又必然会在深入研究中解决 答案 ：D</p><table tabindex="0"><thead><tr><th>解析 ：横线前强调“怀疑”是先导，横线后讲“问题解决”是真知开始，逻辑上为 递进关系 ：怀疑→提出问题→深入研究解决</th></tr></thead></table><p>| 【中航工业2024】人是建筑服务的主要对象，人一直处在不断的繁衍和传播之中，________不同时代的人对建筑物也有不同的要求，________建筑应该新陈代谢，没有必要永久保存。________陵墓建筑________在功能上有耐久的要求，在意象上________与永恒相关，________这里便成了石材发挥作用的主要场所。 A. 所以 因此 而 因为 也 所以； B. 而且 因此 而 不仅 更是 因此； C. 但是 所以 但 不仅 而且 因此； D. 但是 所以 但 因为 也 所以 答案 ：B</p><table tabindex="0"><thead><tr><th>解析 ：第一空“人繁衍传播”到“不同时代要求不同”是 递进关系 （“而且”）；第二空“要求不同”到“建筑新陈代谢”是 因果关系 （“因此”）；第四五空“功能耐久”到“意象永恒”是 递进关系 （“不仅…更是…”</th></tr></thead></table><p>| 【中储粮2018】记得有一位诗人说过这样的话：诗人要做诗，犹如植物要开花，因为他非开不可的缘故。________你摘去吃了，________中了毒，也是你自己的错。 A. 如果 即使； B. 既然 而是； C. 所以 即使 答案 ：A</p><table tabindex="0"><thead><tr><th>解析 ：第一空“摘去吃了”是 假设条件 （“如果”）；第二空“中了毒”是 让步假设 （“即使”）</th></tr></thead></table>',83)])])}const g=_(d,[["render",o]]);export{b as __pageData,g as default};
